<script setup lang="ts">import{ref,computed}from'vue';import StarField from'./components/StarField.vue';import MoonHero from'./components/MoonHero.vue';import BlessingCard from'./components/BlessingCard.vue';import LunarOrbit from'./components/LunarOrbit.vue';import RomanticScroll from'./components/RomanticScroll.vue';import LunarHud from'./components/LunarHud.vue';import FinalScene from'./components/FinalScene.vue';import{journeyFrames,useJourney}from'./composables/useJourney';const open=ref(false),wish=ref('');const{playing,frame,start}=useJourney();const caption=computed(()=>journeyFrames[frame.value].text);function send(v:string){wish.value=v;open.value=false}</script>
<template><main><StarField/><button v-if="!playing" class="start-screen" @click="start"><span>MOONLIGHT 2077</span><strong>点击开启<br/>月光旅程</strong><i>TOUCH TO BEGIN</i></button><Transition name="caption"><aside v-if="playing" class="cinema-caption" :key="caption">{{caption}}</aside></Transition><MoonHero id="hero" @open="open=true"/><Transition name="soft"><aside v-if="wish" class="sent">“{{wish}}”</aside></Transition><LunarOrbit id="orbit"/><RomanticScroll id="romantic"/><LunarHud id="hud"/><FinalScene id="final"/><BlessingCard v-if="open" @close="open=false" @send="send"/></main></template>
